import requests

class RetryableError(Exception):
    """Error worth retrying: rate limit, server error, timeout."""

def classify(resp: requests.Response) -> None:
    if resp.status_code == 429:                   # rate limited
        raise RetryableError("429", resp.headers.get("Retry-After"))
    if 500 <= resp.status_code < 600:             # server problem
        raise RetryableError(str(resp.status_code))
    resp.raise_for_status()                       # other 4xx: a real bug, fail

def get(session: requests.Session, url: str, params: dict) -> dict:
    try:
        resp = session.get(url, params=params, timeout=(3, 10))  # connect, read
    except (requests.Timeout, requests.ConnectionError) as e:
        raise RetryableError("network") from e
    classify(resp)
    return resp.json()

from tenacity import (retry, stop_after_attempt,
                      wait_exponential_jitter, retry_if_exception_type)

@retry(
    wait=wait_exponential_jitter(initial=1, max=30),  # 1s, 2s, 4s... plus random jitter, capped at 30s
    stop=stop_after_attempt(5),                       # give up after 5 tries
    retry=retry_if_exception_type(RetryableError),    # only transient errors
    reraise=True,                                     # surface the last error
)
def fetch_page(session, cursor):
    return get(session, "https://api.example-crm.com/v1/orders",
               {"cursor": cursor, "limit": 500})

import json, pathlib

CHECKPOINT = pathlib.Path("checkpoint.json")

def load_cursor():
    return json.loads(CHECKPOINT.read_text())["cursor"] if CHECKPOINT.exists() else None

def save_cursor(cursor):
    CHECKPOINT.write_text(json.dumps({"cursor": cursor}))

def ingest(session, sink):
    cursor = load_cursor()                       # resume where we stopped
    while True:
        page = fetch_page(session, cursor)
        sink.write(page["data"])                 # store first...
        cursor = page.get("next_cursor")
        save_cursor(cursor)                      # ...then checkpoint
        if not cursor:
            break                                # no more pages

