CREATE TABLE readings (
    sensor_id   bigint       NOT NULL,
    recorded_at timestamptz  NOT NULL,
    value       double precision
) PARTITION BY RANGE (recorded_at);

CREATE TABLE readings_2026_09 PARTITION OF readings
    FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE readings_2026_10 PARTITION OF readings
    FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

-- Index is created on each partition
CREATE INDEX ON readings (sensor_id, recorded_at);

-- Only September's partition is scanned (partition pruning)
EXPLAIN SELECT avg(value) FROM readings
WHERE recorded_at >= '2026-09-20' AND recorded_at < '2026-09-27';

CREATE TABLE claims (
    claim_id   bigint PRIMARY KEY,
    status     text   NOT NULL CHECK (status IN ('open','approved','paid','denied'))
);

CREATE TABLE refunds (
    refund_id  bigserial PRIMARY KEY,
    claim_id   bigint  NOT NULL REFERENCES claims(claim_id),  -- must exist
    amount     numeric(12,2) NOT NULL CHECK (amount > 0),     -- positive only
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (claim_id)                                         -- one refund per claim
);

